// Gebruik de middag om timezone-fouten bij het rekenen in Node-RED te vermijden
let d = new Date(info.start + "T12:00:00Z");
let eindD = new Date(info.eind + "T12:00:00Z");
let eliaTaken = [];

while (d <= eindD) {
    let yyyy = d.getUTCFullYear();
    let mm = String(d.getUTCMonth() + 1).padStart(2, '0');
    let dd = String(d.getUTCDate()).padStart(2, '0');
    let dagStr = `${yyyy}-${mm}-${dd}`;

    let nextD = new Date(d.getTime() + 24*3600*1000);
    let n_yyyy = nextD.getUTCFullYear();
    let n_mm = String(nextD.getUTCMonth() + 1).padStart(2, '0');
    let n_dd = String(nextD.getUTCDate()).padStart(2, '0');
    let nextDagStr = `${n_yyyy}-${n_mm}-${n_dd}`;

    eliaTaken.push({
