let info = msg.payload;
msg.url = `https://api.energy-charts.info/v2/price?bzn=BE&start=${info.start}&end=${info.eind}`;
node.status({ fill: "blue", shape: "dot", text: `Vraagt EPEX ${info.jaar} op...` });
return msg;

let dataset = msg.payload.data;

if (!dataset || !Array.isArray(dataset) || dataset.length === 0) {
    node.status({ fill: "red", shape: "ring", text: "EPEX V2 leeg!" });
    return null;
}

let points = [];

dataset.forEach((record, index) => {
    if (record.timestamp && record.values) {
        let rawVal = Object.values(record.values)[0];
        let p = parseFloat(rawVal);

        if (!isNaN(p)) {
            let d = new Date(record.timestamp);
            let nextRecord = dataset[index+1];

            let isUurData = false;
            if (nextRecord && nextRecord.timestamp) {
                // De absolute tijd verschilt altijd exact 3.600.000 ms, ook tijdens de zomertijd overgang!
                let diffMs = new Date(nextRecord.timestamp).getTime() - d.getTime();
                if (diffMs === 3600000) {
                    isUurData = true;
                }
            }
            if (!nextRecord && d.getMinutes() === 0) {
                isUurData = true; 
            }

            points.push({
                measurement: "epex_kwartier",
                fields: { prijs: p },
                tags: { type: "epex" },
                timestamp: d
            });

            if (isUurData) {
                points.push({ measurement: "epex_kwartier", fields: { prijs: p }, tags: { type: "epex" }, timestamp: new Date(d.getTime() + 15*60000) });
                points.push({ measurement: "epex_kwartier", fields: { prijs: p }, tags: { type: "epex" }, timestamp: new Date(d.getTime() + 30*60000) });
                points.push({ measurement: "epex_kwartier", fields: { prijs: p }, tags: { type: "epex" }, timestamp: new Date(d.getTime() + 45*60000) });
            }
        }
    }
});

node.status({ fill: "green", shape: "dot", text: `${points.length} EPEX records gered!` });
msg.payload = points;
return msg;

